/**
 *
 * MenuRadioItem is a radio menu item managed by useRadioButton, used within MenuRadioItemGroup.
 *
 * [Live Demo](https://www.primereact.org/menu/)
 *
 * @module MenuRadioItem
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { UseRadioButtonChangeEvent, UseRadioButtonExposes, UseRadioButtonProps } from '@primereact/types/headless/radiobutton';
import * as React from 'react';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { MenuPortalInstance } from './MenuPortal.types';
import type { MenuRadioItemGroupContextInterface } from './MenuRadioItemGroup.types';
import type { MenuItemSelectEvent, MenuRootInstance } from './MenuRoot.types';
import type { MenuSubmenuInstance } from './MenuSubmenu.types';
/**
 * Defines passthrough(pt) options type in MenuRadioItem component.
 */
export type MenuRadioItemPassThroughType<E> = PassThroughType<MenuRadioItemInstance, E>;
/**
 * Defines passthrough(pt) options of MenuRadioItem component.
 */
export interface MenuRadioItemPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: MenuRadioItemPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Event fired when the radio item's checked state changes.
 */
export interface MenuRadioItemCheckedChangeEvent extends UseRadioButtonChangeEvent<React.SyntheticEvent> {
    /**
     * Value of the radio item.
     */
    value: unknown;
}
/**
 * Defines valid properties in MenuRadioItem component.
 */
export interface MenuRadioItemProps extends BaseComponentProps<MenuRadioItemInstance, Omit<UseRadioButtonProps, 'onCheckedChange' | 'value'>, MenuRadioItemPassThrough> {
    /**
     * Value of the radio item. Used to determine the checked state against the parent group's value.
     */
    value?: unknown;
    /**
     * When present, it specifies that the item should be disabled.
     */
    disabled?: boolean | undefined;
    /**
     * Whether the menu should close when this radio item is selected.
     * Defaults to `false` for radio items so selecting a value keeps the menu
     * open; set explicitly to `true` to close on each selection.
     * @default false
     */
    closeOnSelect?: boolean | undefined;
    /**
     * Callback fired when the item is activated. Calling
     * `event.preventDefault()` keeps the menu open regardless of
     * `closeOnSelect`.
     */
    onSelect?: (event: MenuItemSelectEvent) => void;
    /**
     * Callback fired when the radio item is selected.
     */
    onCheckedChange?: (event: MenuRadioItemCheckedChangeEvent) => void;
}
/**
 * Defines valid state in MenuRadioItem component.
 */
export interface MenuRadioItemState {
}
/**
 * Defines the methods and properties exposed by MenuRadioItem component.
 * @extends UseRadioButtonExposes
 */
export interface MenuRadioItemExposes extends UseRadioButtonExposes {
    /**
     * Instance of the Menu component.
     */
    menu: MenuRootInstance | undefined | null;
    /**
     * Instance of the MenuSubmenu component.
     */
    submenu: MenuSubmenuInstance | undefined | null;
    /**
     * Instance of the MenuPortal component.
     */
    portal: MenuPortalInstance | undefined | null;
    /**
     * Parent MenuRadioItemGroup context, if any.
     */
    group: MenuRadioItemGroupContextInterface | null;
    /**
     * ID of the item element.
     */
    itemId: string | undefined;
    /**
     * Whether the item is focused or not.
     */
    focused: boolean;
    /**
     * Whether the item is disabled or not.
     */
    isDisabled: boolean;
    /**
     * Whether the item is checked or not.
     */
    checked: boolean;
}
/**
 * Instance of MenuRadioItem component.
 */
export type MenuRadioItemInstance = ComponentInstance<MenuRadioItemProps, MenuRadioItemState, MenuRadioItemExposes>;
